from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient

class OutOfStock(Exception):
    def __init__(self, sku: str):
        self.sku = sku

app = FastAPI()
stock = {"pen": 0, "cup": 3}

@app.exception_handler(OutOfStock)
async def out_of_stock_handler(request: Request, exc: OutOfStock):
    return JSONResponse(status_code=409, content={"error": "out_of_stock", "sku": exc.sku})

def reserve(sku: str) -> None:          # service code: knows nothing about HTTP
    if stock[sku] == 0:
        raise OutOfStock(sku)
    stock[sku] -= 1

@app.post("/orders/{sku}")
def order(sku: str):
    if sku not in stock:
        raise HTTPException(status_code=404, detail=f"Unknown product {sku}")
    reserve(sku)
    return {"ok": True}

c = TestClient(app)
print(c.post("/orders/ink").json())   # {'detail': 'Unknown product ink'}
r = c.post("/orders/pen")
print(r.status_code, r.json())        # 409 {'error': 'out_of_stock', 'sku': 'pen'}

