from typing import Annotated
from fastapi import Depends, FastAPI
from sqlmodel import Field, Session, SQLModel, create_engine, select

class HeroBase(SQLModel):
    name: str = Field(index=True)
    age: int | None = None

class Hero(HeroBase, table=True):
    id: int | None = Field(default=None, primary_key=True)
    secret_name: str

class HeroCreate(HeroBase):
    secret_name: str

class HeroPublic(HeroBase):
    id: int

engine = create_engine("sqlite:///heroes.db", connect_args={"check_same_thread": False})
SQLModel.metadata.create_all(engine)

def get_session():
    with Session(engine) as session:
        yield session

SessionDep = Annotated[Session, Depends(get_session)]
app = FastAPI()

@app.post("/heroes", response_model=HeroPublic, status_code=201)
def create_hero(data: HeroCreate, session: SessionDep):
    hero = Hero.model_validate(data)
    session.add(hero)
    session.commit()
    session.refresh(hero)
    return hero

@app.get("/heroes", response_model=list[HeroPublic])
def list_heroes(session: SessionDep, limit: int = 10):
    return session.exec(select(Hero).limit(limit)).all()

from datetime import datetime, timedelta, timezone
from typing import Annotated
import jwt
from fastapi import Depends, FastAPI, HTTPException
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from pwdlib import PasswordHash

SECRET_KEY = "change-me: load a 32+ byte random secret from settings"
ALGORITHM = "HS256"
hasher = PasswordHash.recommended()
users = {"ann": hasher.hash("s3cret")}        # username -> password hash
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")
app = FastAPI()

@app.post("/token")
def login(form: Annotated[OAuth2PasswordRequestForm, Depends()]):
    hashed = users.get(form.username)
    if not hashed or not hasher.verify(form.password, hashed):
        raise HTTPException(status_code=401, detail="Incorrect username or password")
    exp = datetime.now(timezone.utc) + timedelta(minutes=30)
    token = jwt.encode({"sub": form.username, "exp": exp}, SECRET_KEY, algorithm=ALGORITHM)
    return {"access_token": token, "token_type": "bearer"}

def current_user(token: Annotated[str, Depends(oauth2_scheme)]) -> str:
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])["sub"]
    except jwt.InvalidTokenError:
        raise HTTPException(401, "Invalid token", headers={"WWW-Authenticate": "Bearer"})

@app.get("/me")
def me(user: Annotated[str, Depends(current_user)]):
    return {"user": user}

from fastapi import BackgroundTasks, Depends, FastAPI
from fastapi.testclient import TestClient

log: list[str] = []

def write_log(message: str) -> None:
    log.append(message)                  # pretend this is slow I/O

def audit(background_tasks: BackgroundTasks, q: str | None = None):
    if q:
        background_tasks.add_task(write_log, f"searched {q!r}")

app = FastAPI()

@app.post("/notify/{email}", status_code=202, dependencies=[Depends(audit)])
def notify(email: str, background_tasks: BackgroundTasks):
    background_tasks.add_task(write_log, f"mail sent to {email}")
    return {"queued": True}

r = TestClient(app).post("/notify/ann@example.com?q=shoes")
print(r.json(), log)
# {'queued': True} ["searched 'shoes'", 'mail sent to ann@example.com']

