from typing import Annotated
from fastapi import Depends, FastAPI, HTTPException
from fastapi.testclient import TestClient

events: list[str] = []

def transaction():
    events.append("begin")
    try:
        yield "tx"
        events.append("commit")
    except Exception:
        events.append("rollback")
        raise

app = FastAPI()
Tx = Annotated[str, Depends(transaction, scope="function")]

@app.post("/ok")
def ok(tx: Tx):
    events.append("work")
    return {"done": True}

@app.post("/fail")
def fail(tx: Tx):
    raise HTTPException(status_code=409, detail="conflict")

c = TestClient(app)
c.post("/ok"); c.post("/fail")
print(events)   # ['begin', 'work', 'commit', 'begin', 'rollback']

from typing import Annotated
from fastapi import FastAPI, Form, HTTPException, UploadFile
from fastapi.responses import StreamingResponse
from fastapi.testclient import TestClient

app = FastAPI()
MAX = 1_000_000

@app.post("/upload")
async def upload(file: UploadFile, title: Annotated[str, Form()]):
    if file.content_type != "text/csv":
        raise HTTPException(415, "CSV only")
    data = await file.read(MAX + 1)
    if len(data) > MAX:
        raise HTTPException(413, "File too large")
    return {"title": title, "name": file.filename, "lines": data.count(b"\n")}

@app.get("/export.csv")
def export():
    def rows():
        yield "id,name\n"
        for i in range(3):
            yield f"{i},item-{i}\n"     # produced lazily, chunk by chunk
    return StreamingResponse(rows(), media_type="text/csv")

c = TestClient(app)
r = c.post("/upload", data={"title": "Q1"}, files={"file": ("q1.csv", b"a,b\n1,2\n", "text/csv")})
print(r.json())               # {'title': 'Q1', 'name': 'q1.csv', 'lines': 2}
print(c.get("/export.csv").text.splitlines())   # ['id,name', '0,item-0', '1,item-1', '2,item-2']

from typing import Annotated
from fastapi import FastAPI, Query, WebSocket, WebSocketDisconnect, WebSocketException, status
from fastapi.testclient import TestClient

app = FastAPI()
rooms: dict[str, list[WebSocket]] = {}

@app.websocket("/ws/{room}")
async def chat(websocket: WebSocket, room: str, token: Annotated[str, Query()]):
    if token != "valid":
        raise WebSocketException(code=status.WS_1008_POLICY_VIOLATION)
    await websocket.accept()
    rooms.setdefault(room, []).append(websocket)
    try:
        while True:
            text = await websocket.receive_text()
            for peer in rooms[room]:            # in-process broadcast only
                await peer.send_json({"room": room, "text": text})
    except WebSocketDisconnect:
        rooms[room].remove(websocket)

with TestClient(app).websocket_connect("/ws/lobby?token=valid") as ws:
    ws.send_text("hi")
    print(ws.receive_json())   # {'room': 'lobby', 'text': 'hi'}

