from typing import Annotated
from fastapi import Depends, FastAPI, Query
from fastapi.testclient import TestClient

calls: list[str] = []

def settings():
    calls.append("settings")
    return {"rate": 10}

def parse_limit(limit: Annotated[int, Query(le=100)], s: Annotated[dict, Depends(settings)]):
    calls.append("parse_limit")
    return limit

def count_hit(s: Annotated[dict, Depends(settings)]):
    calls.append("count_hit")             # side effect!

app = FastAPI()

@app.get("/items")
def items(limit: Annotated[int, Depends(parse_limit)], _: Annotated[None, Depends(count_hit)]):
    return {"limit": limit}

c = TestClient(app)
print(c.get("/items?limit=5").json(), calls)   # {'limit': 5} ['settings', 'parse_limit', 'count_hit']
calls.clear()
print(c.get("/items?limit=500").status_code, calls)
# 422 ['settings', 'count_hit']: settings ran once, count_hit ran despite the 422
